'QZ_Not_Running' => 'QZ Tray ba ya aiki a wannan kwamfuta. Sauke shi daga qz.io ka ci gaba da barin shi yana aiki, sannan ka ba wannan shafi izini idan QZ ya tambaya.',
'Detect_Printers' => 'Gano firintoci',
'QZ_Download_Cert' => 'Sauke takardar shaida (override.crt)',
'QZ_Setup_Title' => 'Yadda ake saita bugawa ta QZ Tray (sau ɗaya, a kowace kwamfuta da ke buga lakabi)',
'QZ_Step_Install' => '1. Sanya QZ Tray a wannan kwamfuta — sauke shi kyauta daga qz.io, sannan ka kunna shi ka bar shi yana aiki (yana zama a system tray a Windows ko menu bar a macOS).',
'QZ_Step_Connect' => '2. Haɗa firintar lakabi ta USB ka tabbatar an sanya ta a cikin tsarin aiki (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. Danna maɓallin ⟳ kusa da "Sunan firinta" a sama don gano firintocin wannan kwamfuta, sannan ka zaɓi firintar lakabi. Bar filin fanko don amfani da firintar da aka saba amfani da ita.',
'QZ_Step_Cert' => '4. Don bugawa ba tare da tambayar izini ba, sauke takardar shaida a ƙasa ka kwafa ta zuwa babban fayil ɗin QZ Tray da sunan override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Sannan ka rufe QZ Tray ka sake kunna shi.',
'QZ_Step_Test' => '5. Danna "Buga lakabin gwaji" a ƙasa. Idan QZ Tray ya nemi izini, danna Allow — idan an sanya takardar shaida ba zai sake tambaya ba.',
'QZ_Step_Save' => '6. Danna Submit don adana waɗannan saituna. Yanzu lakabi daga shafin Buga Barcode za su buga kai tsaye a wannan firinta, ba tare da tagar bugawa ta browser ba.',
'QZ_Setup_Note' => 'QZ Tray yana aiki a kwamfutar da kake amfani da ita, don haka wannan yana aiki ko da Stocky yana kan sabar mai nisa. Kowace kwamfuta da ke buga lakabi tana buƙatar QZ Tray.',

