'PWA_Enabled' => 'Kunna manhaja mai iya sanyawa',
'PWA_Enabled_Help' => 'Yana bar browser ya ba da shawarar sanya wannan manhaja a wayoyi, tablet da kwamfutoci, kuma yana ajiye shafuka na aiki ba tare da intanet ba. Kashe shi yana cire tayin sanyawa a ko\'ina kuma yana goge cache a ziyara ta gaba.',
