'Label_Render_Mode' => 'Zana lakabi',
'Label_Render_Mode_Hint' => 'Yadda ake zana lakabi. Rubutun firinta shi ne mafi sauri kuma yana ba da barcode mafi kyau, amma yana buga haruffan Latin na asali ne kawai da rubutun firintar kanta. Hoton samfoti yana sake zana lakabinka daidai — rubutun da ka zaɓa, kowane harshe — kamar yadda manhajojin lakabi na musamman suke yi.',
'Render_Native' => 'Rubutun firinta (mafi sauri)',
'Render_Raster' => 'Hoton samfoti (zane daidai)',
