'Label_Height_Mm' => 'Tsayin lakabi (mm)',
'Label_Size_Hint' => 'Ainihin girman lakabi ɗaya a kan naɗi. Dole ne ya yi daidai da lakabin da aka saka — girman da ba daidai ba yana sa firinta ta nemi tazara a wurin da bai dace ba, don haka kowane lakabi yana buga ƙara nisa daga wurinsa.',
'Calibrate_Labels' => 'Daidaita lakabi',
'Calibrate_Labels_Hint' => 'Firinta tana fitar da wasu lakabi don auna lakabi da tazara. Yi wannan sau ɗaya bayan saka sabon naɗi, ko idan wurin bugawa ya fara karkata.',
'Calibration_Sent' => 'An fara daidaitawa — firinta za ta fitar da wasu lakabi fanko don auna su. Idan ta tsaya, yi bugun gwaji.',
