'Find_Resolution' => 'Nemo dpi',
'Find_Resolution_Hint' => 'Yana buga lakabi biyu masu alamar 203 da 300. Wanda ya dace yana nuna cikakken murabba\'i a kan lakabi da ƙaramin gefe daidai a kowane gefe huɗu; wanda bai dace ba yana rasa gefuna ko ya wuce zuwa lakabi na gaba.',
'Dpi_Test_Sent' => 'Ana buga lakabi biyu masu alamar 203 da 300. Wanda ya dace yana nuna cikakken murabba\'i da ƙaramin gefe daidai a gefe huɗu — saita "Ƙarfin kan firinta" zuwa wannan lamba ka adana.',
'Label_Offset_X' => 'Matsawa a kwance (mm)',
'Label_Offset_X_Hint' => 'Yana matsar da bugu zuwa gefe a kan lakabi. Yi amfani da shi idan rubutu ya yanke a gefe ɗaya — misali 2.5 idan farin lakabi yana tsakiyar takarda mafi faɗi. Daidaita a matakai na 0.5.',
