/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'Jagorar oda',
'Ord_Guide_Intro' => 'Yadda odar da aka yi a shagonka na kan layi take shiga hajojinka da asusunka, da inda ake ainihin rubuta kuɗin.',
'Ord_Guide_Lifecycle_Title' => 'Matsayin oda',
'Ord_Guide_Lifecycle_Pending' => 'Sabuwar oda tana jiran dubawarka. Odar da ke jira ce kawai za a iya tabbatarwa ko soke.',
'Ord_Guide_Lifecycle_Confirmed' => 'Ka karɓi odar. Stocky yana ƙirƙirar sayarwa a ma\'ajiyar da ka zaɓa kuma yana rage haja — wannan sayarwar ita ce rikodin da rahotannin haja, biyan kuɗi da riba ke karanta.',
'Ord_Guide_Lifecycle_Shipped' => 'Ka aika odar. Isarwa ce kawai: an riga an rage haja lokacin da ka tabbatar.',
'Ord_Guide_Lifecycle_Delivered' => 'Abokin ciniki ya karɓi odar. Wannan ne ke fara lokacin mayarwa.',
'Ord_Guide_Lifecycle_Cancelled' => 'An yar da odar kafin tabbatarwa, don haka ba a ƙirƙiri sayarwa ba kuma ba a rage haja ba.',
'Ord_Guide_PaymentStatus_Tip' => 'Ana saita shi a lokacin biya kuma ba a iya gyara shi a nan. Danna don ganin yadda ake rubuta biyan kuɗi.',
'Ord_Guide_Payment_Title' => 'Matsayin biyan kuɗi',
'Ord_Guide_Payment_Intro' => 'Wannan ginshiƙi yana rubuta yadda abokin ciniki ya zaɓi biya a lokacin oda. Shago ne ke saita shi kuma ba a iya gyara shi daga wannan shafi — ana bin diddigin kuɗin kansa a sayarwar da tabbatar da oda ke ƙirƙira.',
'Ord_Guide_Payment_Paid' => 'Abokin ciniki ya riga ya biya ta kan layi ta hanyar ƙofar biyan kuɗi. Tabbatar da oda yana ƙirƙirar sayarwa a matsayin Paid kuma yana rubuta biyan kuɗi maka — babu wani abu da za a yi.',
'Ord_Guide_Payment_Pending' => 'Biya a lokacin isarwa, canja wurin banki ko wata hanyar biya-daga-baya. Tabbatar da oda yana ƙirƙirar sayarwa a matsayin Unpaid, don haka kai za ka rubuta kuɗin da kanka bayan ka karɓa — duba matakan da ke ƙasa.',
'Ord_Guide_Payment_Failed' => 'Ƙofar biyan kuɗi ta ƙi biyan ko abokin ciniki ya bar shi. Ana soke odar kai tsaye.',
'Ord_Guide_MarkPaid_Title' => 'Canza biyan kuɗi daga pending zuwa paid',
'Ord_Guide_MarkPaid_Step1' => 'Tabbatar da oda a nan tukuna — tabbatarwa ce ke ƙirƙirar sayarwa.',
'Ord_Guide_MarkPaid_Step2' => 'Buɗe Sales > All Sales ka nemo wannan sayarwar (abokin ciniki ɗaya, kuma shafin bayanai yana nuna odar kan layi da ta fito daga gare ta).',
'Ord_Guide_MarkPaid_Step3' => 'Buɗe menu na ayyukan layi ka zaɓi Create Payment.',
'Ord_Guide_MarkPaid_Step4' => 'Shigar da adadi, hanyar biya da rana, sannan ka adana. Sayarwar tana matsawa zuwa Partial ko Paid da kanta, bisa adadin.',
'Ord_Guide_MarkPaid_Note' => 'Matsayin biyan kuɗi da ake nunawa a nan yana ci gaba da rubuta zaɓin lokacin oda kuma yana nan kamar yadda yake. Sayarwa ce rikodin lissafi, kuma ita ce ke ciyar da rahotannin biyan kuɗi da riba. Yi amfani da Show Payments a sayarwa don duba ko gyara abin da ka shigar.',
'Ord_Guide_Notes_Title' => 'Abin sani',
'Ord_Guide_Note_Warehouse' => 'Ma\'ajiyar da ka zaɓa lokacin tabbatarwa tana ƙayyade inda ake ɗaukar haja. Ma\'ajiyoyin da ba za su iya ɗaukar dukkan odar ba ana yi musu alamar Out of Stock a wannan jerin.',
'Ord_Guide_Note_Preorder' => 'Kayayyakin pre-order suna tsallake gwajin haja, don haka za a iya tabbatar da odar da ke ɗauke da su ko da adadin bai samu ba tukuna.',
'Ord_Guide_Note_Flagged' => 'Alamar Flagged tana nufin odar ta kama gwajin zamba a lokacin biya. Sa linzami a kan alamar don ganin dalili ka duba odar kafin tabbatar da ita.',
'Ord_Guide_Note_Cancel' => 'Sokewa tana yiwuwa ne kawai yayin da oda ke jira. Da zarar an tabbatar, mayar da ita ta hanyar sayarwa ko mayarwar abokin ciniki.',


