// Variants guide drawer (product form).
'Guide' => 'Jagora',
'Variants_Guide' => 'Jagorar nau’o’i',
'VG_Intro' => 'Kaya mai nau’o’i ana siyar da shi a matsayin nau’o’i da yawa. Gina su daga zaɓuɓɓuka (an ba da shawara) ko a matsayin jeri mai sauƙi na sunaye. Kowane nau’i yana da lambarsa, farashinsa, hotonsa da kayan ajiyarsa.',
'VG_Options_Title' => 'Yanayin zaɓuɓɓuka (Launi, Girma...)',
'VG_Opt_Step1' => 'Bar maɓallin da ke kan katin a kan "Zaɓuɓɓuka".',
'VG_Opt_Step2' => 'Rubuta sunan zaɓi kamar Launi ko Girma, ko ku zaɓi ɗaya daga cikin shawarwarin.',
'VG_Opt_Step3' => 'Rubuta ƙima (misali Ja) ka danna Enter. Maimaita ga kowace ƙima; waƙafi ma yana raba ƙimomi. Danna x a kan ƙima don cire ta.',
'VG_Opt_Step4' => 'Danna "Ƙara zaɓi" don zaɓi na biyu ko na uku (zaɓuɓɓuka 3 a mafi yawa).',
'VG_Opt_Step5' => 'Danna "Samar da nau’o’i". Ana ƙirƙirar layi ɗaya ga kowane haɗi kuma ana gina sunansa ta atomatik, misali "Ja / S".',
'VG_Opt_Step6' => 'Shigar da kuɗin sayo da farashi a kowane layi, ko ku rubuta ƙima a "Sanya a kan duka" ku danna Kuɗin sayo ko Farashi don kwafa ta zuwa kowane layi.',
'VG_Opt_Step7' => 'Ana samar muku da lambobi. Rubuta naku ko ku danna alamar sabuntawa don samar da wata.',
'VG_Opt_Step8' => 'Na zaɓi: yi alama a "Samfuran launi" a kan zaɓi ku zaɓi launi ga kowace ƙima; shago zai nuna shi a matsayin ɗigo mai launi.',
'VG_Rows_Title' => 'Layukan nau’o’i',
'VG_Rows_Text' => 'Kowane layi yana da hoto, lamba, barcode, kuɗin sayo, farashi, farashin jumla da mafi ƙarancin farashin siyarwa. Lokacin ƙirƙirar kaya kuna iya kuma shigar da kayan farko a ajiye ga kowane sito don kowane nau’i. Alamar "Bai cika ba" tana nufin layin ya rasa ƙima ga wani zaɓi.',
'VG_List_Title' => 'Yanayin jeri mai sauƙi',
'VG_List_Text' => 'Rubuta sunan nau’i ka danna Enter (ko ka danna Ƙara) don ƙara layi, sannan ka cike lambarsa da farashinsa. Wannan shi ne tsohon tsari kuma yana nan don kayan da ake da su.',
'VG_Edit_Title' => 'Gyara daga baya',
'VG_Edit_1' => 'Ƙara ƙima ka danna "Samar da nau’o’i": haɗe-haɗen da suka ɓace kawai ake ƙarawa. Layukan da ake da su suna riƙe lambobinsu, farashinsu da tarihinsu.',
'VG_Edit_2' => 'Cire ƙima ko zaɓi yana cire layukan da ke amfani da shi. Layukan da aka riga aka ajiye ana goge su idan kun ajiye kayan, bayan tabbatarwa.',
'VG_Edit_3' => 'Ba za a iya cire nau’in da har yanzu yake da kaya a ajiye ba. Gyara ko canja wurin kayansa tukuna.',
'VG_Edit_4' => 'Komawa "Jeri mai sauƙi" yana riƙe layuka da sunayensu amma yana watsar da ma’anonin zaɓuɓɓuka.',
'VG_Store_Title' => 'A shagon yanar gizo',
'VG_Store_Text' => 'Abokan ciniki suna zaɓar ƙima ɗaya ga kowane zaɓi, misali Launi sannan Girma. Haɗe-haɗen da babu su an kashe su, waɗanda suka ƙare kuma an ja layi a kansu. Nau’in da aka zaɓa shi ne ke shiga kwando.',
