'Upd_Guide_Before_Title' => '1. Kafin ka sabunta',
'Upd_Guide_Before_Download' => 'Sauke {package} na manhajar daga asusun CodeCanyon ɗinka ({path}). Kada ka buɗe shi (extract) — mai sabuntawa yana buƙatar ZIP ɗin daidai yadda aka sauke shi.',
'Upd_Latest_Full_Zip' => 'sabon cikakken kunshin ZIP',
'Upd_Guide_Before_Admin' => 'Tabbatar ka shiga a matsayin mai gudanarwa da ke da izinin {perm}. Babu wani wanda zai iya gani ko gudanar da mai sabuntawa.',
'Upd_Guide_Before_Quiet' => 'Zaɓi lokaci mara cunkoso: yayin sabuntawa manhajar tana shiga yanayin kulawa na ɗan lokaci kuma ana hana sauran masu amfani shiga.',
'Upd_Guide_Before_No_Manual' => 'Hakika {not} buƙatar ka yi madadi da hannu, ka buɗe fayiloli, ka gudanar da umarni, ka gyara fayilolin saiti, ko ka taɓa rumbun bayanai — mai sabuntawa yana yin duk waɗannan kai tsaye. (Tabbas, ƙarin madadi da hannu ba ya cutarwa.)',
'Upd_Not' => 'babu',
'Upd_Guide_Code_Overwritten' => 'Idan ka gyara lambar manhajar da hannu, sabuntawar za ta maye gurbin canje-canjenka. Bayananka, fayilolin da aka ɗora, saituna da .env ana kiyaye su koyaushe.',
'Upd_Guide_Running_Title' => '2. Gudanar da sabuntawa',
'Upd_Guide_Run_Open' => 'Buɗe {path} (wannan shafin) kuma ka tsaya a shafin {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: danna ko ja kunshin da aka sauke zuwa akwatin ɗorawa. Ana ɗora manyan fayiloli a ƙananan guntaye, don haka wannan yana aiki ko a kan shared hosting mai ƙananan iyakokin ɗorawa. Checksum yana kare daga ɗorawar da ta lalace ko ba ta cika ba.',
'Upd_Upload_The_Zip' => 'Ɗora ZIP ɗin',
'Upd_Guide_Run_Validation' => '{auto} bayan ɗorawa (za ka iya sake gudanar da ita da maɓallin {button}). Tsarin yana duba: ingancin ZIP, tsari da cikar kunshin, dacewar siga (ana ƙin komawa zuwa ƙaramar siga), sigar PHP da ƙarin abubuwan (extensions) da ake buƙata, izinin fayiloli, sararin faifai, haɗin rumbun bayanai, saiti, kuma cewa babu wani sabuntawa da ke gudana.',
'Upd_Validation_Runs_Automatically' => 'Tantancewa tana gudana kai tsaye',
'Upd_Guide_Run_Review' => 'Duba faifan {panel}. Maɓallin {button} yana bayyana ne kawai idan kowane muhimmin bincike ya wuce. Idan bincike ya kasa, saƙon yana gaya maka daidai abin da za ka gyara.',
'Upd_Guide_Run_Click' => 'Danna {button} ka tabbatar. Sannan kawai {keep} ka kalli sandar ci gaba. Tsarin yana aiwatar da waɗannan, bi da bi:',
'Upd_Keep_Page_Open' => 'ka bar wannan shafin a buɗe',
'Upd_Guide_Phase_Backup' => '{label} — ana ƙirƙirar cikakken kwafin rumbun bayanai, ZIP na kowane fayil na manhaja da sabuntawar za ta iya canzawa, da kwafin {env}, kuma ana {verified} su. Fayilolin da ka ɗora ({images}) da {storage} sabuntawa ba ta taɓa su, don haka ba a adana su. Idan ba a iya ƙirƙirar madadi ba, sabuntawar tana tsayawa a nan kuma babu abin da zai canza.',
'Upd_Verified' => 'tabbatar da',
'Upd_Guide_Phase_Prepare' => '{label} — ana buɗe sabuwar sigar a wurin shiri kuma ana sake tantance ta. Ba a taɓa manhajar da ke aiki ba tukuna.',
'Upd_Guide_Phase_Maintenance' => '{label} — ana kunna yanayin kulawa; masu ziyara suna ganin allon "Za mu dawo nan ba da jimawa ba" mai daɗi.',
'Upd_Guide_Phase_Files' => '{label} — ana sauya sabbin fayiloli kusan nan take; ana ajiye tsofaffin fayiloli a gefe don komawa baya. Ba a taɓa maye gurbin hanyoyin da aka kare ({env}, {storage}, {images}).',
'Upd_Guide_Phase_Database' => '{label} — ana gudanar da migrations, sannan ana sabunta izini, fassarori da samfura.',
'Upd_Guide_Phase_Cache' => '{label} — ana share duk cache kuma a sake gina su.',
'Upd_Guide_Phase_Verify' => '{label} — binciken lafiya yana tabbatar da cewa sabuwar sigar tana farawa, rumbun bayanai yana aiki, duk migrations sun gudana, kuma saiti yana da inganci.',
'Upd_Guide_Phase_Done' => '{label} — ana cire yanayin kulawa kuma ana tsabtace fayilolin wucin gadi.',
'Upd_Guide_Run_Success' => 'Idan ka ga {success}, danna {reload} kuma ka sake sabunta burauzarka gaba ɗaya ({keys}) don sabbin fayilolin faifan gudanarwa su loda.',
'Upd_Update_Successful_Short' => 'Sabuntawa ta yi nasara',
'Upd_Guide_No_Internet' => 'Ba a buƙatar haɗin intanet yayin sabuntawa — komai yana fitowa daga ZIP ɗin da aka ɗora. Rasa haɗin intanet ko rufe burauza BA ya karya sabuntawar: sabar tana tuna daidai inda ta tsaya.',
'Upd_Guide_Wrong_Title' => '3. Idan wani abu ya lalace',
'Upd_Guide_Wrong_Rollback' => '{label} — idan wani abu ya kasa bayan fayiloli sun fara canzawa (kuskuren buɗewa, gazawar migration, gazawar binciken lafiya, faifai ya cika, …), tsarin yana maido da fayilolin baya da rumbun bayanai kai tsaye daga madadin da aka tabbatar, yana cire yanayin kulawa, kuma yana ba da rahoton {message}. Za ka koma daidai inda ka fara.',
'Upd_Automatic_Rollback' => 'Komawa baya kai tsaye',
'Upd_Failed_Previous_Restored' => 'Sabuntawa ta kasa — an maido da sigar baya',
'Upd_Guide_Wrong_Interrupted' => '{label} (sake kunna sabar, ƙarewar lokaci, rufe burauza, ɗaukewar wuta) — idan ka sake buɗe wannan shafin, tuta ja tana ba da zaɓuɓɓuka biyu masu aminci: {resume} (yana ci gaba daga daidai matakin da ya tsaya) ko {rollback} (yana maido da sigar baya daga madadi).',
'Upd_Interrupted_Update' => 'Sabuntawar da aka katse',
'Upd_Guide_Wrong_Unreachable' => '{label} — yi amfani da {console} mai zaman kansa a {path}. Yana aiki ko da shafin yana cikin yanayin kulawa ko fayilolin faifan gudanarwa sun lalace, kuma yana ba da ayyukan Ci gaba / Komawa baya iri ɗaya. Akwai kuma ɓoyayyen mahaɗin "Administrator access" (Shiga na mai gudanarwa) a ƙasan allon kulawa.',
'Upd_Admin_Unreachable' => 'Ba a iya isa faifan gudanarwa',
'Upd_Recovery_Console' => 'allon farfaɗowa',
'Upd_Guide_Wrong_Locked_Out' => '{label} — yayin da sabuntawa ke gudana, wannan shafin yana nuna {link}. Ajiye shi idan kana buƙatar sake shiga (misali bayan zamanka ya ƙare); yana ba ka damar wuce allon kulawa don ka sake shiga.',
'Upd_Locked_Out_Maintenance' => 'Yanayin kulawa ya hana shiga',
'Upd_Bypass_Link' => 'mahaɗin wucewa',
'Upd_Guide_Wrong_Concurrent' => '{label} — za su ga {message} Sabuntawa ɗaya kawai ke iya gudana a lokaci guda.',
'Upd_Another_Admin_Updating' => 'Wani mai gudanarwa yana ƙoƙarin sabuntawa a lokaci guda',
'Upd_Guide_Backups_Title' => '4. Madadi & maidowa',
'Upd_Guide_Backups_Created' => 'Kowane sabuntawa yana ƙirƙirar madadi {before} ya taɓa komai: duk fayilolin manhaja da sabuntawar za ta iya maye gurbinsu, kwafin {env}, da cikakken kwafin rumbun bayanai. Sabuntawa ba ta taɓa canza fayilolin da aka ɗora da {storage}, don haka ba sa cikin madadin — ka riƙe naka madadin waɗannan. Madadi suna zaune a {path} kuma ba a taɓa isa gare su daga yanar gizo.',
'Upd_Before' => 'kafin',
'Upd_Guide_Backups_Panel' => 'Faifan {panel} a shafin {tab} yana jera su da kwanan wata, siga da girma. Daga nan za ka iya {restore} kowane cikakken madadi (fayiloli + rumbun bayanai — ana fara ɗaukar kwafin tsaro na rumbun bayanai na yanzu) ko {delete} tsofaffi.',
'Upd_Restore_Verb' => 'maido da',
'Upd_Delete_Verb' => 'goge',
'Upd_Guide_Backups_Retention' => 'Yi amfani da {keep} don zaɓar madadi nawa za a riƙe; ana cire tsofaffi kai tsaye bayan kowace sabuntawa mai nasara. Madadi cikakke ɗaya tilo da ya rage ba za a taɓa goge shi ba — koyaushe kana da hanyar komawa baya.',
'Upd_Guide_Manual_Title' => '5. Sabuntawa da hannu (hanyar madadi)',
'Upd_Guide_Manual_Text' => 'Idan kun fi son sabuntawa da hannu, ko ba za a iya amfani da mai ɗora fayil ɗin a sabar ku ba, ku bi umarnin mataki-mataki a shafin {tab} na wannan shafi.',
'Upd_Guide_Clear_Cache_First' => 'Idan shafuka sun lalace ko sun zama fanko bayan kowace sabuntawa, ku fara share cache na burauzar ku — kusan koyaushe shi ne sanadi.',
'Upd_Restore_Backup_Confirm' => 'A dawo da wannan ajiyar madadi? Fayilolin yanzu da database na yanzu za a maye gurbinsu da ajiyar. Za a fara ɗaukar kwafin kariya na database na yanzu. (v{version} — {date})',
'Woo_Guide_Lead' => 'Yadda shagon WooCommerce ke kasancewa daidai da ERP. An gina layukan cron da ke ƙasa domin wannan sabar, don haka ana iya kwafa su kai tsaye a kanta.',
'Woo_Guide_Ways_Note' => 'Ba kamar Shopify ba, WooCommerce ba ya aika komai zuwa ERP da kansa — babu mai karɓar webhook a nan, don haka duk abin da ke shigowa {in} yana zuwa ne bisa jadawali. Kaya a ajiye da ke fita {out} ne kawai zai iya zama nan take.',
'Woo_In' => 'ciki',
'Woo_Out' => 'waje',
'Woo_Guide_Both_Ways_Title' => 'Duk hanyoyin biyu suna buƙatar wannan da farko',
'Woo_Api_Keys' => 'Maɓallan API',
'Woo_Guide_Api_Keys_Text' => '{path}, izini {perm}. Kwafi consumer key da secret zuwa shafin {settings}, tare da URL na shago — adireshin shafin ku ba tare da slash a ƙarshe ba, misali {example}.',
'Woo_Credentials_Saved' => 'an ajiye bayanan shiga',
'Woo_Not_Configured_Yet' => 'ba a saita ba tukuna',
'Woo_Guide_Wp_App_Password_Title' => 'Kalmar sirrin aikace-aikace ta WordPress (na zaɓi)',
'Woo_Guide_Wp_App_Password_Text' => 'Ana amfani da ita ne kawai don hotunan kaya. API na WooCommerce yana motsa kaya, kaya a ajiye, rukunoni, tambura, abokan ciniki da oda; API na WordPress ne ke bincika Media Library kuma yana ɗora hoton da babu shi a can tukuna.',
'Woo_Guide_Wp_App_Password_Note' => 'Yi amfani da mai amfani na WordPress wanda zai iya sarrafa media, kuma ku ƙirƙiri kalmar sirrin a ƙarƙashin {path}. Ku bar filayen biyu fanko kuma komai zai ci gaba da daidaitawa — haɗa hoto ne kawai za a tsallake.',
'Woo_Guide_Pick_Way_Title' => 'Sannan zaɓi yadda zai ci gaba da kasancewa daidai',
'Woo_Right_Away' => 'Nan take',
'Woo_Stock_Live' => 'kaya a ajiye kai tsaye',
'Woo_Stock_Not_Live' => 'kaya a ajiye ba kai tsaye ba',
'Woo_Guide_Realtime_Lead' => 'Hanya ɗaya kawai: kaya a ajiye da kaya da ke barin ERP. Oda da gyaran kaya da aka yi a WooCommerce har yanzu suna zuwa bisa jadawali — duba ɗayan shafin.',
'Woo_Push_Stock_On_Change' => 'Tura kaya a ajiye a lokacin da ya canza',
'Woo_Setting_People_Miss' => 'Wannan ita ce saitin da mutane ke mantawa',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Siyarwar POS {not} isa WooCommerce da kanta. Idan an kashe shi, shagon zai sani ne kawai a daidaita kaya a ajiye na gaba — awa ɗaya, a tsoho — kuma a cikin wannan lokacin zai iya sayar da kayan da kuka riga kuka sayar a kanti.',
'Woo_Does_Not' => 'ba ta',
'Woo_Guide_Tick_Instant' => 'Yi alama a {option} a shafin {settings}. Wannan shi ne duk saitin — babu worker, babu cron. Kowace siyarwa, mayarwa, gyara, canja wuri da siyan kaya da aka karɓa za ta aika turawar waɗannan kayan kawai, nan da nan bayan an ajiye siyarwar, kuma siyarwa mai layuka ashirin tana ɗaukar turawa ɗaya ne, ba ashirin ba. Kanti ba ya taɓa jira.',
'Woo_Currently' => 'A yanzu:',
'Woo_Instant_On_Text' => 'a kunne — ana tura kaya a ajiye idan ya canza',
'Woo_Instant_Off_Text' => 'a kashe — kaya a ajiye bisa jadawali kawai',
'Woo_Guide_Instant_Note' => 'Kaya da aka riga aka haɗa da WooCommerce ne kawai ake turawa — wanda ba a taɓa daidaitawa ba ba shi da komai a shago da za a gyara. Kaya masu nau’i suna bi ta mahaifinsu, kuma ana sake tura combo idan ɗaya daga cikin abubuwan da ke cikinsa ya motsa. Ayyuka masu yawa (goge kaya, sake saita sito) suna rubuta kaya a ajiye ba tare da kunna wani al’amari ba, wanda shi ne dalili ɗaya na ci gaba da daidaita kaya a ajiye na kowace awa.',
'Woo_Push_Products_On_Save' => 'Tura kaya a lokacin da aka ajiye su',
'Woo_Guide_Tick_Auto_Products' => 'Yi alama a {option} a shafin {settings} kuma kayan da aka ƙirƙira, aka gyara ko aka kwafa a Stocky za a aika shi zuwa WooCommerce nan da nan bayan an ajiye shi — bayanai, farashi, nau’o’i da hotuna, sannan kaya a ajiye nasa. Ana ƙirƙirar sabon kaya a shago nan take maimakon jiran daidaita kaya na dare.',
'Woo_On' => 'a kunne',
'Woo_Off' => 'a kashe',
'Woo_Guide_Bulk_Imports_Note' => 'Ba a tura shigo da kaya masu yawa ɗaya bayan ɗaya — ku gudanar da daidaita kaya bayan shigo da su. Ku fara daidaita rukunoni da tambura, domin kayan da aka tura ya sauka a rukunin da ya dace.',
'Woo_Nothing_Else_To_Install' => 'Babu wani abu da za a girka',
'Woo_Guide_Same_Process' => 'Babu queue worker, babu shigarwar cron. Turawar tana gudana a cikin aikin da ya yi wa siyarwar hidima, {after} amsar ta koma, don haka kanti ba ya taɓa jiran WooCommerce. Turawa ba sa haɗuwa: canje-canjen da aka yi yayin da ɗaya ke gudana suna jiran sa kuma suna fita nan da nan bayan haka.',
'Woo_After' => 'bayan',
'Woo_Guide_Shop_Stops_Answering' => 'Shagon da ya daina amsawa ana barin sa bayan daƙiƙa takwas, kuma turawa suna tsayawa na mintuna biyar domin kada kowace siyarwa ta sake jiran sa; canje-canjen da suka shigo a wannan lokacin suna fita da turawar farko bayan tsayawar, kuma daidaita kaya a ajiye na kowace awa yana cike gibin ko ta yaya. Ana rubuta kowace tsayawa a shafin Logs.',
'Woo_Guide_Artisan_Exception' => 'Banda ɗaya: canjin kaya a ajiye da umarnin artisan ya yi ba shi da amsar da zai zo bayanta, don haka ana sa shi a layin {queue} maimakon haka. Domin waɗannan su ma su fita da sauri, ku zubar da wannan layin:',
'Woo_Cron_Line_Copied' => 'An kwafi layin cron',
'Woo_Command_Copied' => 'An kwafi umarni',
'Woo_Guide_Not_Woo_Queue' => 'Da gangan ba layin {queue} ba: wannan yana ɗauke da rukunin kundin kaya da ke ɗaukar awanni, kuma turawar nan take da aka sa a bayan ɗaya ba za ta zama nan take ba.',
'Woo_On_A_Schedule' => 'Bisa jadawali',
'Woo_Guide_Scheduled_Lead' => 'Ana sake duba komai lokaci zuwa lokaci, ta hanyoyi biyu. Haka oda ke isa ERP, haka ake wallafa kundin kaya, kuma wannan ne ke gyara duk abin da hanyar sauri ta rasa. Kowane aiki yana da shigarwar cron nasa, don haka kuna gudanar da abin da kuke so kawai.',
'Woo_Guide_Sync_Drains_Queue' => '{command} yana zubar da layinsa yayin da yake gudana, don haka waɗannan layukan ba sa buƙatar worker daban. A Windows, yi amfani da Task Scheduler tare da shirin {program} da gardama iri ɗaya, an fara a {path}.',
'Woo_Or_No_Cron' => 'Ko babu cron kwata-kwata',
'Woo_Guide_No_Cron_Text' => 'Kowane shafi a nan yana daidaitawa idan an buƙata, kuma daidaitawa da hannu yana zubar da rukunoninsa yayin da shafin a buɗe yake — don haka ƙaramin shago zai iya aiki ba tare da kowace shigarwar cron ba. Abin da kuke rasawa shi ne duk abin da ke faruwa yayin da babu mai kallo: oda suna zuwa ne kawai idan wani ya danna maɓallin.',
'Woo_Commands_Worth_Knowing' => 'Umarnin da ya kamata a sani',
'Woo_Worth_Knowing' => 'Ya kamata a sani',
'Woo_Guide_Changing_Url_Clears' => 'Canza URL na shago ko maɓallan API yana share kowace haɗi — kaya, rukunoni, tambura da abokan ciniki duk suna sake daidaitawa zuwa sabon shagon.',
'Woo_Guide_Keep_Skus' => 'Ku kiyaye SKU iri ɗaya tsakanin Stocky da WooCommerce: wannan ne ke hana kwafi kuma shi ne ke sa sake haɗawa ya zama lafiya.',
