'Woo_Settings_Instant_Hint' => 'Siyarwa, mayarwa ko gyara yana aika turawar kaya a ajiye na waɗannan kayan kawai a lokacin da aka ajiye shi, don haka shagon yana daidai cikin daƙiƙoƙi maimakon a daidaita kaya a ajiye na awa mai zuwa. Babu wani abu da za a girka — turawar tana gudana bayan an amsa siyarwar, don haka kanti ba ya taɓa jiran WooCommerce. Ƙarin bayani a shafin {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Idan an bar shi a kashe, siyarwar POS tana isa WooCommerce ne kawai a daidaita kaya a ajiye na gaba — har zuwa awa ɗaya daga baya.',
'Woo_Settings_Auto_Products_Hint' => 'Kayan da aka ƙirƙira, aka gyara ko aka kwafa a Stocky ana aika shi zuwa WooCommerce nan da nan bayan an ajiye shi — bayanai, farashi, nau’o’i, hotuna, sannan kaya a ajiye nasa — maimakon jiran daidaita kaya. Ba a tura shigo da kaya masu yawa; ku gudanar da daidaita kaya bayan shigo da su.',
'Woo_Sync_Tuning' => 'Gyaran daidaitawa',
'Woo_Sync_Tuning_Intro' => 'Tsoffin ƙima sun dace da yawancin shaguna. Ku canza waɗannan ne kawai idan daidaitawa yana jinkiri ko yana ƙarewa lokaci a hosting ɗinku. Kowace ƙima an iyakance ta zuwa iyaka mai lafiya, kuma share fili yana dawo da tsohuwar ƙimarsa.',
