'Telegram_G_Cron_Note' => 'Kowane minti daidai ne: gudanarwa da babu abin da ke jira tana fita nan take. A cPanel wannan yana shiga {cronJobs} — yi amfani da cikakken hanyar PHP 8.2+ idan {php} ya tsufa. A Windows, yi amfani da Task Scheduler tare da shirin {program}, gardama {args}, an fara a {path}.',
