'Presta_From_Menu' => 'Daga {menu}',
'Presta_Webservice_Key_Help' => 'Kunna webservice a PrestaShop ({menu}), ƙirƙiri maɓalli mai izini akan products, stock_availables, orders da customers, kuma liƙa shi a nan. An ajiye don rubutu kawai.',
