'Presta_Shop_Language_Help' => 'Id na harshe da ake amfani da shi don sunayen kaya yayin turawa (1 = harshen farko na shagon).',
'Presta_Push_Products_Desc' => 'Yana ƙirƙirar kaya masu sauƙi da ba su nan a PrestaShop (tare da kaya a ajiye na yanzu). Ana tsallake kaya da aka riga aka haɗa da kaya masu nau’o’i — ci gaba da gyara bayanan kaya a PrestaShop, ko jawo don sabunta kwafin gida.',
'Presta_Pull_Products_Desc' => 'Yana shigo da kayan PrestaShop, yana daidaita waɗanda ke akwai ta manuni (SKU) kuma yana ƙirƙirar sauran. Ana shigo da haɗe-haɗe (combinations) a matsayin kayan mahaifinsu.',
'Presta_Reset_Product_Confirm' => 'A sake saita haɗin kaya? Tarihin oda yana riƙe haɗinsa.',
'Presta_Push_Stock_Desc' => 'Yana sabunta kaya a ajiye na shagon (stock_availables) ga kowane kaya da aka haɗa.',
'Presta_Pull_Orders_Desc' => 'Yana shigo da odar shago a matsayin siyarwa (manuni kamar {ref}), sababbi da farko. Ana tsallake oda da aka riga aka shigo da su da waɗanda aka soke, don haka jawowa akai-akai lafiya ne. PrestaShop ba shi da webhooks — ku gudanar da wannan bayan lokutan cunkoso.',
'Presta_Guide_1' => 'A cikin back office na PrestaShop ɗinku, buɗe {menu} kuma ku kunna webservice.',
'Presta_Guide_2' => 'Ƙara sabon maɓalli, ku ba da {rw} akan {products} da {stock}, da {view} akan {orders} da {customers}.',
'Presta_Guide_3' => 'Liƙa URL na shago da maɓallin a shafin Connection, ajiye, kuma ku gudanar da {test}.',
'Presta_Guide_4' => 'Fara jawo kaya idan shagon yana da kundin kaya (yana daidaitawa ta manuni/SKU); tura don ƙirƙirar kaya masu sauƙi da ba su nan.',
'Presta_Guide_5' => 'Tura kaya a ajiye duk lokacin da yawa ya canza, kuma ku jawo oda akai-akai — PrestaShop ba shi da webhooks, don haka oda suna zuwa ne kawai idan kun jawo.',
'Presta_Identity_Title' => 'Shaidar kaya ita ce manuni (SKU)',
'Presta_Identity_Desc' => 'Ana daidaita lambar kaya ta Stocky da manuni na PrestaShop. Ku kiyaye manuni iri ɗaya a ɓangarorin biyu; ana daidaita haɗe-haɗe (nau’o’i) a cikin oda ta manuni amma ba a tura su a wannan sigar.',
