'Jumia_Push_Prices_Stock' => 'Tura farashi & kaya a ajiye',
'Jumia_Pull_Orders_Desc' => 'Yana shigo da odar kasuwa a matsayin siyarwa (manuni kamar {ref}), ana daidaita su da kayanku ta Seller SKU. Ana tsallake oda da aka riga aka shigo da su da waɗanda aka soke, don haka jawowa akai-akai lafiya ne. Ana alamta biya a matsayin an biya ne kawai ga oda da aka isar (Jumia galibi biya-bayan-isarwa ce, COD).',
