'Jumia_Guide_3' => 'Tabbatar cewa {sku} na kowane jerin Jumia ya yi daidai da lambar kaya ta Stocky — wannan ita ce shaidar da ake amfani da ita don turawar kaya a ajiye da daidaita oda.',
