'Jumia_Guide_5' => 'Ƙirƙirar sabbin jerin kaya yana nan a Seller Center — Jumia tana buƙatar halaye na musamman na kowane rukuni da duba hotuna waɗanda tashar su kaɗai ke sarrafawa da kyau.',
