'Shopify_G_Credentials' => 'Bayanan shaidar Shopify',
'Shopify_G_Cred_Intro' => 'Tun Janairu 2026 Shopify ba ya ƙirƙirar manhajoji na musamman a cikin admin, don haka akwai nau’ikan haɗi biyu:',
'Shopify_G_Cred_DevDash' => '{app} (duk shagon da aka haɗa yanzu) — {path}. Ba da izinin Admin API scopes na abin da wannan shagon ke daidaitawa, girka manhajar a shagon, sannan kwafi {clientId} da {clientSecret} daga shafin Saituna na manhajar zuwa {where}. ERP na musanya su da access token da kansa kuma yana sabunta shi kafin ya ƙare duk bayan awa 24. Client secret na kuma sa hannu a Webhook, don haka ba a buƙatar komai kuma. Dole ne manhajar da shagon su kasance a ƙungiyar Shopify ɗaya.',
'Shopify_G_Dev_Dashboard_App' => 'Manhajar Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (wanda aka ƙirƙira a admin kafin 2026) — tana ci gaba da aiki ba tare da canji ba da {token} ({prefix}) ɗinta da {secret} ɗinta a matsayin sirrin sa hannun Webhook. Ba ƙima ɗaya ba ce da token ɗin, kuma musanya su ba daidai ba shi ne dalilin da aka saba ƙin Webhook.',
'Shopify_G_Legacy_App' => 'Tsohuwar manhaja ta musamman',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'an ajiye',
'Shopify_G_Missing_Refused' => 'babu — za a ƙi isarwa',
'Shopify_G_Where_Data_Desc' => '{path} Sito na ERP wanda wannan shagon ke siyar da kayansa, da wurin Shopify da ake rubuta waɗannan kaya a ajiye zuwa gare shi. Daidaitawar kaya a ajiye da shigo da oda duka ba za su gudana ba sai da su.',
'Shopify_G_Currently' => 'A yanzu: sito {warehouse}, wuri {location}',
'Shopify_G_Not_Set_Lower' => 'ba a saita ba',
'Shopify_G_Ready' => 'a shirye',
'Shopify_G_Incomplete' => 'bai cika ba',
'Shopify_G_Manual_Syncs' => 'Daidaitawar da kake farawa da hannu',
'Shopify_G_Manual_Desc' => 'Daidaitawar da aka fara daga {centre} na amsawa nan take kuma tana gudana a bayan fage, cikin ƙananan yanka da kowanne ke ci gaba daga inda na baya ya tsaya. Babban kundin kaya ba zai taɓa yankewa a tsakiya ba saboda hosting da ke katse dogayen buƙatun yanar gizo (LiteSpeed, nginx, load balancer), kuma rufe shafin ba ya dakatar da shi. Ma’aikacin (worker) da ke yin hakan wani ƙarin layin cron ne:',
'Shopify_G_Cron_Copied' => 'An kwafi layin cron',
'Shopify_G_Manual_Note' => 'Idan babu shi daidaitawa za ta gama duk da haka, amma sai idan shafin Sync Centre ya kasance a buɗe: idan babu worker da ya ɗauki gudanarwa cikin ’yan daƙiƙoƙi, shafin zai ci gaba da ita da kansa, buƙata ɗaya gajeriya a lokaci ɗaya. A Windows yi amfani da Task Scheduler kowane minti: program {program}, arguments {args}, started in {dir}.',
'Shopify_G_Then_Pick' => 'Sannan zaɓi yadda zai ci gaba da kasancewa daidai',
'Shopify_G_Right_Away' => 'Nan take',
'Shopify_G_Stock_Live' => 'kaya a ajiye kai tsaye',
'Shopify_G_Stock_Not_Live' => 'kaya a ajiye ba kai tsaye ba',
'Shopify_G_Realtime_Lead' => 'Ana aika kowane canji yayin da yake faruwa, cikin daƙiƙoƙi. Rabi biyu ne, kuma maɓallan kunnawa daban-daban ne: {webhooks} na shigo da lamuran shagon, {push} kuma na aika kaya a ajiye waje.',
'Shopify_G_Webhooks_Lower' => 'Webhook',
'Shopify_G_Instant_Push_Lower' => 'turawar kaya a ajiye nan take',
'Shopify_G_Webhooks_In' => 'Webhook — shago → ERP',
'Shopify_G_Webhooks_Desc' => 'Oda, canje-canjen matsayin oda, da gyaran kaya, abokan ciniki da kaya a ajiye da aka yi a Shopify. Buɗe shagon ka danna {button} a {tab} ɗinsa — ba matsala idan an danna sau biyu. Shopify na aikawa zuwa:',
'Shopify_G_Webhooks_Tab' => 'shafin Webhook',
'Shopify_G_Webhooks_Note' => 'Dole ne a iya isa ga adireshin daga intanet ta HTTPS — Shopify ba zai isar zuwa {localhost} ko domain na {test} ba. Ana rubuta kowace isarwa sau ɗaya, don haka sake gwadawar Shopify ba za ta iya ƙirƙirar oda biyu ba, kuma ana iya sake kunna wadda ta gaza. Ana ƙin isarwa har sai an ajiye sirrin sa hannu daga mataki na 1.',
'Shopify_G_Instant_Out' => 'Turawar kaya a ajiye nan take — ERP → shago',
'Shopify_G_Setting_Missed' => 'Wannan ita ce saitin da mutane ke mantawa',
'Shopify_G_Pos_Not_Auto' => 'Siyarwar POS {not} isa Shopify da kanta. Idan a kashe yake, shagon zai sani ne kawai a matakin turawar Kaya a ajiye na gaba — kuma a wannan tazarar zai iya siyar da raka’a da ka riga ka siyar a rajistar kuɗi.',
'Shopify_G_Not' => 'ba ta',
'Shopify_G_Tick_Push' => 'Duba {setting} a {where}. Wannan shi ne duk saitin — babu worker, babu cron. Kowace siyarwa, mayarwa da gyara za su aika turawar waɗannan kayan kaɗai, nan da nan bayan an ajiye siyarwar, kuma siyarwa mai layi ashirin turawa ɗaya take ci, ba ashirin ba. Rajistar kuɗi ba ta taɓa jiran ta.',
'Shopify_G_This_Store' => 'Wannan shagon:',
'Shopify_G_Push_On' => 'a kunne — ana tura kaya a ajiye idan sun canza',
'Shopify_G_Push_Off' => 'a kashe — kaya a ajiye bisa jadawali kawai',
'Shopify_G_Push_Note' => 'Kayan da suka riga suna da haɗin Shopify kaɗai, da motsi a sito na wannan shagon kaɗai, ake turawa. Ayyukan gungu — goge kaya, sake saita sito — suna rubuta kaya a ajiye ba tare da harba wani lamari ba, wanda shi ne dalili ɗaya na ci gaba da riƙe matakin kaya a ajiye na jadawali.',
'Shopify_G_Nothing_Install' => 'Babu wani abu da za a girka',
'Shopify_G_No_Worker_Note' => 'Babu ɗaya daga cikin rabin biyun da ke buƙatar queue worker ko shigarwar cron. Webhook mai shigowa ana sarrafa shi a cikin buƙatar da Shopify ya yi; turawar kaya a ajiye mai fita na gudana a cikin aikin (process) da ya yi hidimar siyarwar, {after} amsar ta koma — don haka rajistar kuɗi ba ta taɓa jiran Shopify, kuma shagon da ya daina amsawa ana barin shi bayan daƙiƙa goma a bar shi ga turawar kaya a ajiye ta jadawali ta gaba.',
'Shopify_G_After' => 'bayan',
'Shopify_G_Artisan_Note' => 'Banbanci ɗaya: canjin kaya a ajiye da umarnin artisan ya yi ba shi da amsar da zai biyo baya, don haka ana sanya shi a jerin jira a {queue} maimakon haka. Idan kana son su ma su fita da wuri, gudanar da wannan jerin jiran:',
'Shopify_G_On_Schedule' => 'Bisa jadawali',
'Shopify_G_On_Lower' => 'a kunne',
'Shopify_G_Off_Lower' => 'a kashe',
'Shopify_G_Scheduled_Lead' => 'Ana sake duba komai lokaci-lokaci, ta hanyoyin biyu. Ya fi lokaci na gaske jinkiri, amma shi ne ke tura kaya a ajiye a shagunan da ba sa amfani da turawa nan take, shi ne ke kama Webhook da aka rasa, kuma shi ne kaɗai hanyar motsa kundin kaya gaba ɗaya.',
'Shopify_G_Cron_Entry' => 'Shigarwar cron',
'Shopify_G_Cron_Entry_Desc' => 'Babu abin da aka tsara da zai gudana sai da ita. Layi ɗaya, na wannan module kaɗai — ƙara shi kusa da duk wani abu da ka zaɓa ka tsara:',
'Shopify_G_Cron_Note' => 'Kowane minti biyar shi ne mafi ƙanƙantar tazarar da tsari zai iya amfani da ita, saboda minti biyar ita ce mafi gajeriyar tazarar mataki. Shigarwa mafi tsayi tana zama mafi ƙanƙanta kawai — da {example}, matakin da aka saita zuwa minti 5 zai gudana kowane minti 15. A Windows yi amfani da Task Scheduler: program {program}, arguments {args}, started in {dir}.',
'Shopify_G_Switch_On_Plan' => 'Kunna shi, kuma zaɓi tsarin',
'Shopify_G_Plan_Desc' => '{where} Maɓallin kunnawa ne ke yanke shawarar ko cron zai iya yin aiki kwata-kwata; tsarin ne ke yanke abin da zai yi. {step} abu ɗaya ne ta hanya ɗaya da tazararsa ta kansa — {first}, {second}. Ana amfani da tazara ta asali a kowane mataki da ya bar akwatinsa babu komai.',
'Shopify_G_Step_Lower' => 'mataki',
'Shopify_G_Plan_Note' => 'Bar tsarin babu komai kuma shagon zai jawo oda ya tura kaya a ajiye a tazara ta asali, wanda shi ne abin da yawancin shaguna ke so. Oda jawowa kawai ake yi: a Shopify ne abokin ciniki ke yin oda.',
'Shopify_G_Schedule_On' => 'jadawali a kunne',
'Shopify_G_Schedule_Off' => 'jadawali a kashe — da hannu kawai',
'Shopify_G_When_Step_Runs' => 'Yaushe mataki ke gudana a zahiri',
'Shopify_G_When_Note' => 'Lokacin mataki na yi idan lokacin da wannan matakin ya {started} a karo na ƙarshe ya wuce tazararsa, ana karanta wannan daga tarihin gudanarwa. Don haka daidaitawar da ka fara da hannu tana jinkirta ta atomatik ta gaba, kuma matakin da ke ci gaba da gazawa ana sake gwada shi bisa tazararsa maimakon a kowane bugu. Overview na shago na nuna gudanarwa ta ƙarshe ta kowane mataki, lokacin da zai yi na gaba, da dalilin da ya sa aka hana shi idan haka ne. Gudanar da turawar kundin kaya ta farko da hannu — da {dryRun} da farko — kafin ka sanya ta a jadawali.',
'Shopify_G_Started_Lower' => 'fara',
'Shopify_G_Where_Setting' => 'Inda kowace saiti take',
'Shopify_G_Where_Setting_Note' => 'Duk waɗannan suna kan shagon da ke akwai: {path}, sannan fensir (ko {edit} a shafin shagon na kansa).',
'Shopify_G_Product_Images' => 'Hotunan kaya',
'Shopify_G_Img_1' => 'Hotuna na fita tare da kaya a {push} — babban hoto da farko, sannan gallery, sannan ɗaya ga kowane nau’i da ke da nasa, har zuwa hamsin.',
'Shopify_G_Products_Push' => 'turawar kaya',
'Shopify_G_Img_2' => 'Ana loda hoton nau’i tare da kayan sannan a {assigned}, haka Shopify ke tsara shi: nau’i na nuna ɗaya daga cikin hotunan kayan. Nau’in da ke sake amfani da babban hoto ba ya loda shi sau biyu.',
'Shopify_G_Assigned' => 'sanya shi ga wannan nau’in',
'Shopify_G_Img_3' => 'Hoton da aka ajiye a matsayin fayil ana {uploaded} shi zuwa Shopify, ba a haɗa shi ta link ba, don haka yana aiki ko da ba a iya isa ga wannan shigarwar daga intanet. Hoton da aka ƙara a matsayin link da aka liƙa ana miƙa shi ga Shopify a matsayin wannan URL ɗin, wanda dole ne kowa ya iya isa gare shi.',
'Shopify_G_Uploaded' => 'loda',
'Shopify_G_Img_4' => 'Ana sake aika su ne kawai idan sun canza a zahiri — turawar da ke canza farashi kawai ba ta taɓa hotunan shagon, saboda aika su na maye gurbin duk tarin.',
'Shopify_G_Img_5' => 'Idan aka cire hoto a ERP, manhajar {not} goge shi a Shopify. Goge shi a can ma, ko shagon zai ci gaba da nuna shi.',
'Shopify_G_Commands' => 'Umarnin da ya kamata a sani',
'Shopify_G_Command_Copied' => 'An kwafi umarni',
'Shopify_G_Foot' => 'Kowace daidaitawa na rubutawa zuwa {logs}, kuma Overview na kowane shago na nuna lokacin da kowane mataki ya gudana na ƙarshe, lokacin da zai yi na gaba, da abin da ke hana shi idan akwai. A nan ya kamata ka fara dubawa idan daidaitawa ba ta yi abin da kake tsammani ba.',
'Shopify_G_Covers' => 'Ya ƙunshi',
'Shopify_G_Covers_Rt' => 'Oda da gyare-gyaren da aka yi a Shopify; kaya a ajiye da ke fita daga ERP (siyarwar POS, mayarwa, gyara)',
'Shopify_G_Covers_Sch' => 'Komai, ta hanyoyin biyu — har da turawar kundin kaya da duk abin da hanya mai sauri ta rasa',
'Shopify_G_Speed' => 'Gudu',
'Shopify_G_Speed_Rt' => 'Daƙiƙoƙi',
