'Shopify_G_Needs' => 'Yana buƙata',
'Shopify_G_Needs_Rt' => 'Adireshin HTTPS na jama’a da sirrin sa hannu don Webhook masu shigowa. Kaya a ajiye masu fita ba sa buƙatar komai',
