'StoreAdm_Stock_Required_Available' => '{name}: Ana buƙata {need} — Akwai {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash da SSLCommerz ana amfani da su ne a wurin biyan kuɗi na SHAGON YANAR GIZO kaɗai.',
'StoreAdm_PG_Intro_Desc' => 'Ana raba maɓallan Stripe a ko’ina (admin da shagon yanar gizo suna amfani da haɗin Stripe ɗaya). Kowane shafi na kunna ko kashe hanyarsa don wurin biyan kuɗi na shagon yanar gizo; Biyan kuɗi na waje (Offline Payments) na ɗauke da hanyoyin da ake biya a wajen tsarin.',
'StoreAdm_PG_Used_By_Store_Only' => 'Wurin biyan kuɗi na shagon yanar gizo kaɗai ke amfani da shi',
