'StoreAdm_PG_Cards_Off' => 'An kashe biyan kuɗi da kati',
'StoreAdm_PG_Cards_Off_Desc' => 'Ana riƙe maɓallanka — wurin biyan kuɗi na shagon yanar gizo kawai zai daina bayar da zaɓin kati har sai ka sake kunna shi.',
'StoreAdm_PG_No_Stripe_Key' => 'Babu maɓallin Stripe da aka ajiye',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'Shigar da maɓalli da sirrin Stripe ɗinka don fara karɓar biyan kuɗi da kati a shagon yanar gizo.',
'StoreAdm_PG_Gw_Client_Id' => '{gw} Client ID',
'StoreAdm_PG_Gw_Client_Secret' => '{gw} Client Secret',
'StoreAdm_PG_Sandbox' => 'Sandbox (yanayin gwaji)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'A KUNNE yana amfani da {sandbox} da bayanan shaidar sandbox; KASHE shi don cajin asusun gaske a {live}.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => '{gw} Webhook ID (ba tilas ba)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'Madadin kariya don biyan kuɗin da komawar burauza ba ta taɓa sauka ba, tare da mayar da kuɗi/chargebacks. Yi rajistar Webhook a {site} da ke nuna URL ɗin da ke ƙasa (lamura: {events}) kuma liƙa Webhook ID ɗinsa a nan.',
'StoreAdm_PG_Webhook_Url' => 'URL na Webhook:',
'StoreAdm_PG_Gw_Disabled' => 'An kashe {gw}',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Kunna PayPal kuma shigar da Client ID da Secret na manhajar REST ɗinka (daga {site}) don bari abokan ciniki su biya da PayPal a wurin biyan kuɗi na shagon yanar gizo.',
'StoreAdm_PG_Gw_Public_Key' => '{gw} Public Key',
'StoreAdm_PG_Gw_Secret_Key' => '{gw} Secret Key',
'StoreAdm_PG_Paystack_Test_Live' => 'Gwaji ko na gaske ana yanke shi ne da nau’in maɓallan: maɓallan {test} na aiki a yanayin gwaji, maɓallan {live} na cajin katunan gaske — babu wani maɓallin sandbox daban.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'URL na Webhook (madadin kariya ba tilas ba — saita shi a ƙarƙashin Settings → API Keys & Webhooks a Dashboard na Paystack; ana tabbatar da buƙatu da HMAC ta amfani da secret key ɗinka):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Kunna Paystack kuma shigar da Public da Secret keys ɗinka (daga {site} → Settings → API Keys) don karɓar kati, canja wurin banki da kuɗin waya a wurin biyan kuɗi na shagon yanar gizo.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (Webhook, ba tilas ba)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'Secret Hash da ka saita a ƙarƙashin Settings → Webhooks a Dashboard na Flutterwave; ana ƙin Webhook masu shigowa sai idan header ɗinsu na {header} ya yi daidai.',
'StoreAdm_PG_Flutterwave_Info' => 'Yana amfani da Flutterwave v3 API da maɓallai na gargajiya. Gwaji ko na gaske ana yanke shi ne da nau’in maɓallan ({keys} ko maɓallan gaske) — babu wani maɓallin sandbox daban. Dole ne a kunna kuɗin shagon a asusun Flutterwave ɗinka.',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'URL na Webhook (madadin kariya ba tilas ba — saita shi tare da Secret Hash da ke sama a Dashboard na Flutterwave):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'Kunna Flutterwave kuma shigar da v3 Public da Secret keys ɗinka (daga {site} → Settings → API) don karɓar kati, kuɗin waya da canja wurin banki a wurin biyan kuɗi na shagon yanar gizo.',
'StoreAdm_PG_Gw_Key_Id' => '{gw} Key ID',
'StoreAdm_PG_Gw_Key_Secret' => '{gw} Key Secret',
'StoreAdm_PG_Webhook_Secret_Opt' => 'Webhook Secret (ba tilas ba)',
'StoreAdm_PG_Razorpay_Secret_Hint' => 'Sirrin da ka ayyana lokacin ƙirƙirar Webhook a Dashboard na Razorpay; ana tabbatar da lamura masu shigowa da HMAC bisa shi, idan ba haka ba ana ƙin su.',
'StoreAdm_PG_Razorpay_Info' => 'Yana amfani da Razorpay Payment Links (kati, UPI, netbanking, walat). Gwaji ko na gaske ana yanke shi ne da nau’in maɓallan ({keys}) — babu wani maɓallin sandbox daban.',
'StoreAdm_PG_Razorpay_Webhook_Url' => 'URL na Webhook (madadin kariya ba tilas ba — yi masa rajista tare da sirrin da ke sama a ƙarƙashin Settings → Webhooks; lamura: {events}):',
'StoreAdm_PG_Razorpay_Disabled_Desc' => 'Kunna Razorpay kuma shigar da Key ID da Key Secret ɗinka (daga {site} → Settings → API Keys) don karɓar kati, UPI, netbanking da walat a wurin biyan kuɗi na shagon yanar gizo.',
'StoreAdm_PG_Gw_App_Key' => '{gw} App Key',
'StoreAdm_PG_Gw_App_Secret' => '{gw} App Secret',
'StoreAdm_PG_Gw_Username' => 'Sunan mai amfani na {gw}',
'StoreAdm_PG_Gw_Password' => 'Kalmar sirri ta {gw}',
