'StoreAdm_PG_Bkash_Info' => 'Yana amfani da bKash Tokenized Checkout (bayanan shaidar ɗan kasuwa daga tashar ’yan kasuwa ta bKash). bKash na caji da BDT kaɗai — ana bayar da zaɓin a wurin biyan kuɗi ne kawai idan kuɗin shagon da ke aiki BDT ne.',
