'Cr_Guide_Step_Cod' => 'Zaɓi inda kuɗin COD za su je',
'Cr_Guide_Step_Cod_Help' => 'A Saitunan kamfanin isar da kaya, zaɓi asusun da ake rubuta kuɗin COD a ciki, da yadda ake sarrafa fakitin da aka mayar da kuɗaɗen kamfanin isar da kaya.',
