'Cr_Guide_Good_To_Know' => 'Abin da ya kamata ka sani',
'Cr_Guide_Webhooks' => 'Adiresoshin webhook',
'Cr_Guide_How' => 'Yadda ake yin rajistarsa',
'Cr_Guide_How_It_Works' => 'Yadda yake aiki',
'Cr_Guide_Meaning' => 'Ma’ana',
'Cr_Guide_T_Statuses' => 'Matsayi',
'Cr_Guide_Statuses_Note' => 'Matsayi suna ci gaba ne kawai, don haka sabuntawar da ta makara ba za ta taɓa mayar da fakiti baya ba. Fakitin da aka isar har yanzu ana iya bayar da rahotonsa a matsayin ana mayarwa ko an mayar.',
