'Cr_Guide_S_returning' => 'Yana kan hanyar dawowa gare ka.',
'Cr_Guide_S_returned' => 'Ya dawo gare ka: yana jira a Mayarwa don dubawa, ko kuma a mayar da shi cikin kaya a ajiye ta atomatik.',
'Cr_Guide_S_cancelled' => 'An soke rijistar.',
'Cr_Guide_T_Booking' => 'Yin rijistar oda',
'Cr_Guide_B_Booking' => 'Aika zuwa kamfanin isar da kaya yana cike fom daga siyarwar: mai karɓa, adireshi, adadin da ya rage a matsayin COD, da nauyin kayan. Kamfanonin isar da kaya masu jerin garuruwansu suna nuna zaɓi, kuma ana tuna zaɓinka don wannan gari. Masu tara kamfanoni, DHL, FedEx, UPS da Lalamove suna ba da Kwatanta farashi: zaɓi farashi sai Yi rijista ya saya. Ana iya yin rijistar siyarwa da yawa lokaci ɗaya daga jerin siyarwa.',
'Cr_Guide_T_Cod' => 'Biya bayan isarwa',
'Cr_Guide_B_Cod' => 'Fakitin COD yana tafiya daga Ba a karɓa ba zuwa Kamfanin isar da kaya ya karɓa (lokacin isarwa) zuwa An biya ka. Kamfanonin isar da kaya da ke bayar da rahoton biya suna motsa mataki na ƙarshe da kansu; don sauran yi amfani da Sabunta COD. Idan an zaɓi asusu a Saitunan kamfanin isar da kaya, ana rubuta biyan a matsayin biya a kan siyarwar. Ana iya ajiye kuɗaɗen kamfanin isar da kaya a matsayin kuɗaɗen fita da zarar fakiti ya kammala.',
'Cr_Guide_T_Returns' => 'Fakitin da aka mayar',
'Cr_Guide_B_Returns' => 'Ta tsohuwa fakitin da aka mayar yana jira a Jigilar kamfanin isar da kaya ƙarƙashin Mayarwa don dubawa. Mayar cikin ajiya yana ƙirƙirar mayarwar siyarwa ga dukan odar kuma yana mayar da kayan cikin kaya a ajiye; Watsar ba ya mayar da komai, don fakitin da suka lalace ko suka ɓace. Saitunan kamfanin isar da kaya za su iya mayar da su cikin ajiya ta atomatik maimakon haka.',
'Cr_Guide_T_Customers' => 'Saƙonnin abokan ciniki da shafin bin diddigi',
'Cr_Guide_B_Customers' => 'Sanarwar abokan ciniki a Saitunan kamfanin isar da kaya suna aika SMS, email ko WhatsApp a matsayin da ka zaɓa, kowanne sau ɗaya ga kowane fakiti, da rubutunka. Shafin bin diddigi a shagonka na yanar gizo yana barin abokan ciniki su bi fakiti ta lambar bin diddigi, ko ta lambar oda da waya. Abokan ciniki da ke yawan mayar da fakiti suna samun alamar haɗarin mayarwa lokacin da kake yin rijista.',
'Cr_Guide_T_Labels' => 'Lakabobi',
'Cr_Guide_B_Labels' => 'Buga lakabi yana ba da lakabin kamfanin isar da kaya idan ya fitar da shi (PDF, hanyar haɗi ko hoto), in ba haka ba lakabin Stocky mai barcode na bin diddigi da adadin da za a karɓa. Ba da izinin pop-up don wannan shafin don bugawa. DHL, FedEx da UPS suna ba da lakabinsu sau ɗaya kawai, lokacin rijista, kuma Stocky yana ajiye shi don sake bugawa.',
'Cr_Guide_T_Faq' => 'Magance matsaloli',
'Cr_Guide_Q_Test' => 'Gwajin haɗi ya gaza',
'Cr_Guide_A_Test' => 'Maɓallan yanayin gwaji suna tafiya da Yanayin gwaji, maɓallan aiki kuma da Live; sun bambanta. Buɗe Bayanan kamfanin isar da kaya ka karanta amsar kamfanin don ainihin dalili.',
'Cr_Guide_Q_City' => 'Kamfanin isar da kaya ya ƙi gari ko adireshi',
'Cr_Guide_A_City' => 'Zaɓi garin daga jerin garuruwan kamfanin isar da kaya a fom ɗin rijista; kamfanonin suna karɓar sunayensu kawai. Kamfanonin da ke aiki da adireshin gidan waya kuma suna buƙatar jiha, lambar gidan waya da ƙasa mai haruffa biyu.',
'Cr_Guide_Q_Webhook' => 'Matsayi ba sa canzawa da kansu',
'Cr_Guide_A_Webhook' => 'Don kamfanonin da ke turawa, tabbatar an yi rajistar URL na webhook a wurin kamfanin isar da kaya: Bayanan kamfanin isar da kaya suna nuna kowace sabuntawa da aka karɓa, ko dalilin da yasa aka ƙi ta (misali sirrin da ba daidai ba). Ana duba sauran kamfanoni bisa jadawalin da ke Saitunan kamfanin isar da kaya, kuma Duba matsayi yanzu yana tambaya nan take.',
'Cr_Guide_Q_Stuck' => 'Jigila tana nuna kuskuren duba matsayi',
'Cr_Guide_A_Stuck' => 'Kamfanin isar da kaya ya ƙi binciken ƙarshe; dalilin yana kan jigilar da kuma a Bayanan kamfanin isar da kaya. Bayan gazawa da yawa, ba a ƙara duba jigila ta atomatik: gyara dalilin, sannan ka yi amfani da Duba matsayi yanzu.',
'Cr_Guide_Q_Label' => 'Babu abin da ke buɗewa lokacin buga lakabi',
'Cr_Guide_A_Label' => 'Burauzarka ta toshe pop-up. Ba da izinin pop-up don wannan shafin ka sake gwadawa.',
'Cr_Guide_Q_Cod' => 'Ba a rubuta biyan COD a kan siyarwar ba',
'Cr_Guide_A_Cod' => 'A Saitunan kamfanin isar da kaya, biya bayan isarwa yana buƙatar a kunna maɓallin kuma a zaɓi asusu. Ba tare da asusu ba, ana yi wa biyan alama ne kawai a matsayin an biya.',
