'Tfa_Codes_Save' => 'Ajiye waɗannan lambobin farfaɗowa a wuri mai aminci. Kowace ɗaya tana shigar da kai sau ɗaya idan ka rasa wayarka. Ba za a sake nuna su ba.',
'Tfa_Reset' => 'Sake saita matakai biyu',
'Tfa_Reset_Title' => 'Sake saita tabbatarwa ta matakai biyu?',
'Tfa_Reset_Help' => ':name zai shiga da kalmar sirrinsa kawai sannan zai iya sake saita manhajar tabbatarwarsa. Yi haka ne kawai bayan tabbatar da wanda ke tambaya.',
'Tfa_Guide_Lead' => 'Tabbatarwa ta matakai biyu (2FA) tana ƙara mataki na biyu ga shiga: bayan kalmar sirri, ma’aikata suna rubuta lambar lambobi 6 daga manhajar tabbatarwa a wayarsu. Kalmar sirri da aka sace ko aka hasashe ba za ta ƙara isa don shiga ba.',
'Tfa_Guide_State_Required' => 'Ana buƙata',
'Tfa_Guide_State_Optional' => 'A’a — na zaɓi ga kowa',
