'Tfa_Guide_State_Users' => 'Masu amfani da 2FA a kunne',
'Tfa_Guide_Staff_Title' => 'Ga kowane ma’aikaci',
'Tfa_Guide_App_Title' => 'Sanya manhajar tabbatarwa',
'Tfa_Guide_App_Text' => 'Kowace manhaja da ke tallafa wa daidaitattun lambobi 6 (TOTP) tana aiki. Kyauta ne kuma suna aiki ba tare da intanet ba:',
'Tfa_Guide_Enable_Title' => 'Kunna shi daga bayanan martaba',
'Tfa_Guide_Enable_1' => 'Buɗe Bayanan martaba (menu na hoto a saman dama) ka nemo katin "Tabbatarwa ta matakai biyu".',
'Tfa_Guide_Enable_2' => 'Danna "Kunna" ka tabbatar da kalmar sirri ta yanzu.',
'Tfa_Guide_Enable_3' => 'Duba lambar QR da manhajar, ko rubuta maɓallin da aka nuna a ƙarƙashinta.',
'Tfa_Guide_Enable_4' => 'Shigar da lambar lambobi 6 da manhajar ke nunawa don kammalawa.',
'Tfa_Guide_Open_Profile' => 'Buɗe bayanan martabata',
'Tfa_Guide_Codes_Title' => 'Ajiye lambobin farfaɗowa',
'Tfa_Guide_Codes_Text' => 'Nan da nan bayan saitawa, ana nuna lambobin farfaɗowa 8 sau ɗaya. Kowace ɗaya tana maye gurbin lambar waya sau ɗaya — don wayar da ta ɓace, ta lalace ko aka sake saita ta. Sauke ko kwafa su ka ajiye su a wuri mai aminci, nesa da wayar.',
'Tfa_Guide_Codes_Note' => 'Sun kusa ƙarewa? "Sabbin lambobin farfaɗowa" a bayanan martaba yana maye gurbin dukan jerin; tsofaffin suna daina aiki.',
'Tfa_Guide_Signin_Title' => 'Shiga',
'Tfa_Guide_Signin_Text' => 'Bayan email da kalmar sirri, shafin shiga yana tambayar lambar yanzu daga manhajar. Lambobi suna canzawa kowane daƙiƙa 30 kuma kowace ɗaya tana aiki sau ɗaya.',
'Tfa_Guide_Signin_Trust' => 'Zaɓar "Kada a sake tambaya a wannan na’urar" yana tsallake lambar a wannan burauzar na kwanaki :days.',
'Tfa_Guide_Signin_Recovery' => 'Babu waya a hannu? Danna "Yi amfani da lambar farfaɗowa" ka rubuta ɗaya daga cikin lambobin da aka ajiye.',
'Tfa_Guide_Admin_Title' => 'Ga masu gudanarwa',
'Tfa_Guide_Require_Title' => 'Sanya shi ya zama dole',
'Tfa_Guide_Require_Text' => 'Kunna "Wajabta tabbatarwa ta matakai biyu" a wannan katin, sannan ka zaɓi matsayin da dole su yi amfani da shi — ko ka bar jerin babu komai ga kowane mai amfani. Danna Aika don ajiyewa.',
'Tfa_Guide_Require_Next' => 'Ba a fitar da kowa ba. Masu amfani da ba su da 2FA tukuna za a jagorance su wajen saitawa a shafin shiga a shigarsu ta gaba, kafin su shiga, kuma za su ga lambobin farfaɗowarsu a can.',
'Tfa_Guide_Require_Note' => 'Masu amfani da aka wajabta musu ba za su iya kashe shi daga bayanan martabarsu ba.',
'Tfa_Guide_Trust_Title' => 'Na’urori amintattu',
'Tfa_Guide_Trust_Text' => '"Tuna na’urori amintattu" yana saita tsawon lokacin da burauza za ta iya tsallake lambar bayan shiga cikin nasara. Zaɓi "Kullum a tambayi lamba" don kwamfutoci na tarayya ko na jama’a kamar POS na cikin shago.',
'Tfa_Guide_Trust_Note' => 'Rage adadin yana gajarta na’urorin da aka riga aka amince da su; kashe 2FA ko sake saita shi yana manta da su duka.',
'Tfa_Guide_Lost_Title' => 'Waya ta ɓace kuma babu lambobin farfaɗowa',
'Tfa_Guide_Lost_Text' => 'A shafin Masu amfani, masu amfani da 2FA suna nuna "A kunne" a ginshiƙin 2FA. Maɓallin garkuwa a Ayyuka yana sake saita shi: mai amfani yana shiga da kalmar sirri kawai kuma yana sake saita manhajar (ko a tambaye shi ya yi, idan ana buƙata).',
'Tfa_Guide_Lost_Warn' => 'Tabbatar da wanda ke tambaya kafin sake saitawa — sake saitawa yana cire kariyar da 2FA ke ba wa wannan asusu.',
'Tfa_Guide_Open_Users' => 'Buɗe Masu amfani',
'Tfa_Guide_Mobile_Title' => 'Manhajar waya da API',
'Tfa_Guide_Mobile_Text' => 'Manhajar waya da hanyar token na API suna tambayar lambar iri ɗaya. Idan ana buƙatar 2FA ga mai amfani da bai saita shi ba tukuna, dole ne ya shiga ta yanar gizo sau ɗaya don yin haka.',
'Tfa_Guide_Protect_Title' => 'Kariya da aka gina a ciki',
'Tfa_Guide_Protect_1' => 'Lambobi 5 marasa daidai suna toshe shigar da lamba ga wannan mai amfani na mintuna 15, ko da menene saitunan kullewa da ke sama.',
'Tfa_Guide_Protect_2' => 'Kowace lamba da kowace lambar farfaɗowa tana aiki sau ɗaya kawai.',
'Tfa_Guide_Protect_3' => 'Idan "Rubuta ayyukan shiga" yana kunne, lambobin da ba daidai ba suna bayyana a jerin Ayyukan shiga a matsayin "Lambar 2FA ba daidai ba".',
'Tfa_Guide_Trouble_Title' => 'Magance matsaloli',
'Tfa_Guide_Faq_Clock_Q' => '“Wannan lambar ba ta da inganci” da sabuwar lamba',
'Tfa_Guide_Faq_Clock_A' => 'Mai yiwuwa agogon wayar ba daidai ba ne. Lambobi sun dogara da lokaci: saita kwanan wata da lokacin wayar zuwa atomatik (lokacin hanyar sadarwa), sannan ka gwada lamba ta gaba.',
'Tfa_Guide_Faq_Phone_Q' => 'Komawa zuwa sabuwar waya',
'Tfa_Guide_Faq_Phone_A' => 'Ko dai ka yi amfani da fasalin canja wuri na manhajar tabbatarwar kanta, ko ka kashe 2FA a bayanan martaba ka sake kunna shi da sabuwar wayar (idan ana buƙata, ka roƙi mai gudanarwa ya sake saita shi maimakon haka).',
'Tfa_Guide_Faq_Locked_Q' => '“Lambobi marasa inganci sun yi yawa”',
'Tfa_Guide_Faq_Locked_A' => 'Jira lokacin da aka nuna (har zuwa mintuna 15), ko ka sa mai gudanarwa ya sake saita 2FA na mai amfanin.',
'Tfa_Guide_Faq_Key_Q' => 'Babu mai 2FA da zai iya shiga bayan an canja sabar',
'Tfa_Guide_Faq_Key_A' => 'An ɓoye sirrin 2FA da APP_KEY da ke cikin fayil ɗin .env. Ci gaba da amfani da APP_KEY ɗaya lokacin canja wuri ko dawo da manhajar; idan ya canza, dole ne mai gudanarwa mara 2FA ya sake saita masu amfanin da abin ya shafa.',
'Tfa_Guide_Button' => 'Jagora',
'Tfa_Guide_Title' => 'Jagorar tabbatarwa ta matakai biyu',
'Sec_2fa_Pending' => ':count har yanzu ba su saita shi ba',
'Sec_2fa_See_Who' => 'Ga su waye',
'Sec_2fa_Grace_Off' => 'Babu — a saita a shiga ta gaba',
'Sec_2fa_Applied' => 'An fitar da mai amfani :count.',
'Tfa_Guide_Rollout_Title' => 'Ƙaddamar da shi ga kowane mai amfani',
'Tfa_Guide_Rollout_1' => 'Fara kunna shi a asusunka (Bayanan martaba), don ka san matakan.',
'Tfa_Guide_Rollout_2' => 'Gaya wa ƙungiyarka manhajar da za su sanya kuma cewa saitawa tana ɗaukar minti ɗaya lokacin shiga.',
'Tfa_Guide_Rollout_3' => 'Kunna "Wajabta tabbatarwa ta matakai biyu", bar "Ana buƙata don" babu komai (= kowane mai amfani), kuma idan kana so zaɓi lokacin jinkiri. Danna Aika.',
'Tfa_Guide_Rollout_4' => 'Danna "Fitar da masu amfani marasa 2FA" domin waɗanda suka riga sun shiga su saita shi yanzu maimakon a wata shiga ta gaba. Kai za ka ci gaba da kasancewa a ciki.',
'Tfa_Guide_Rollout_5' => 'Bi ci gaba da ma’aunin da ke wannan katin, ko matatar "Yana buƙatar saitawa" a shafin Masu amfani.',
'Tfa_Guide_Rollout_Note' => 'Idan akwai lokacin jinkiri, allon saitawa yana nuna “Tunatar da ni daga baya” har zuwa ranar ƙarshe; bayan haka, saitawa ta zama dole don shiga.',
'Tfa_Guide_Customers_Title' => 'Asusun abokan ciniki (shago da Tashar abokan ciniki)',
'Tfa_Guide_Customers_Text' => 'Abokan ciniki ma za su iya kare asusunsu. Na zaɓi ne ga kowane abokin ciniki kuma ba a taɓa tilastawa: kunna shi a Saitunan shago → Ikon samun damar rajista (shagon yanar gizo) da Tashar abokan ciniki → Saitunan Portal (Tashar abokan ciniki).',
'Tfa_Guide_Customers_1' => 'Abokan ciniki suna kunna shi daga Asusuna (shago) ko Bayanan martaba (Portal).',
'Tfa_Guide_Customers_2' => 'Suna zaɓar lambar da ake aikawa ta email — mafi sauƙi, ba a buƙatar manhaja — ko manhajar tabbatarwa tare da lambobin farfaɗowa.',
'Tfa_Guide_Customers_3' => 'Lambobin da ake aikawa ta email suna buƙatar saitunan wasiƙa masu aiki (Saituna → Saitunan wasiƙa). Suna ƙarewa bayan mintuna 10.',
'Tfa_Guide_Customers_4' => 'Kashe zaɓin daga baya yana dakatar da sabbin saitawa; abokan cinikin da suka riga suna amfani da shi za a ci gaba da tambayar su kuma za su iya kashe shi da kansu.',
'Tfa_Required_Grace_Notice' => 'Mai gudanarwarka yana buƙatar tabbatarwa ta matakai biyu. Za ka iya jinkirta shi lokacin shiga har zuwa :date; bayan haka, saitawa ta zama dole.',
'Tfa_Filter_All' => '2FA: duk masu amfani',
'Tfa_Needs_Setup_Help' => 'Saitunan tsarin > Tsaro ne suka wajabta; za a tambaye shi ya saita shi a shiga ta gaba.',
