'Sec_2fa_Grace' => 'Lokacin jinkiri',
'Sec_2fa_Grace_Help' => 'Yana barin masu amfani su zaɓi “Tunatar da ni daga baya” a allon saitawa har zuwa ranar ƙarshe, domin kada a tsayar da kowa a tsakiyar aiki. Ana ƙirgawa daga lokacin da aka kunna buƙatar.',
