'Sec_2fa_Apply' => 'Aiwatar yanzu',
'Sec_2fa_Apply_Help' => 'Waɗanda suka riga sun shiga ana tambayar su ne kawai a shigarsu ta gaba, wanda zai iya ɗaukar watanni da “Ka tuna da ni”. Wannan yana fitar da duk wanda dole ya saita 2FA kuma bai yi ba, a kowace na’ura, domin su saita shi lokacin da suka sake shiga. Kai za ka ci gaba da kasancewa a ciki.',
